import React from "react";
import { Link } from "react-router-dom";
import ex from "../../../img/exx.png";
import "../../../App.css";

const PublicNavbar = () => {
  return (
    <nav className="fixed top-0 left-0 w-full z-50 bg-[#5e5d96] shadow-md px-6 py-3 flex justify-between items-center">
      {/* Brand / Logo */}
      <Link to="/" className="flex items-center">
        <img className="h-10 w-auto md:ml-10" src={ex} alt="Expense Manager" />
      </Link>

      {/* Mobile Menu Button (Static visual for Tailwind - requires state for toggle in React) */}
      <button className="md:hidden text-white focus:outline-none">
        <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" />
        </svg>
      </button>

      {/* Nav Links & Auth Buttons */}
      <div className="hidden md:flex items-center space-x-8 w-full justify-between ml-10">
        <ul className="flex space-x-6">
          <li>
            <Link to="/" className="text-white hover:text-gray-200 font-medium transition-colors">
              Home
            </Link>
          </li>
        </ul>
        
        <div className="flex items-center space-x-6 pr-10">
          <Link
            to="/login"
            className="text-white hover:text-gray-200 font-medium transition-colors"
          >
            Sign In
          </Link>
          <Link
            to="/register"
            className="bg-white text-[#5e5d96] px-5 py-2 rounded-md font-semibold hover:bg-gray-100 transition-colors shadow-sm"
          >
            Sign Up
          </Link>
        </div>
      </div>
    </nav>
  );
};

export default PublicNavbar;
